PG.stores=()=>head(['Butiker'],'Butiker')+`<div class="bsbody"><h2>Hantera dina butiker</h2><table class="bt" style="margin-top:12px"><tr><th>Butik</th><th>Adress</th><th>Kassor</th></tr><tr><td>Kaffebaren</td><td>Storgatan 1, 111 22 Stockholm</td><td>1</td></tr></table></div>`;
PG.wh=()=>head(['Lagerplatser'],'Lagerplatser')+`<div class="bsbody"><h2>Lagerplatser</h2><p class="lead">Platser där du har lager utanför butikerna, t.ex. ett centrallager.</p><div class="rowr">${actPill('Lägg till ny lagerplats','bswh','wh-add')}</div><table class="bt"><tr><th>Namn</th><th>Typ</th></tr>${D().locations.map(l=>`<tr data-g="wh-${slug(l.name)}"><td>${esc(l.name)}</td><td>${l.wh?'Lagerplats':'Butik'}</td></tr>`).join('')}</table>
 ${B().dlg==='wh'?dlg('Lägg till ny lagerplats',`${lbl('Namn',1)}${inp('b_whname')}<div style="margin-top:10px">${lbl('Adress')}${inp('b_whaddr')}</div>`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bswhok" data-g="wh-save">Spara</button>`,{h:300}):''}</div>`;
