sub('ostore','Onlinebutik','ostores');BACK.ostore='ostores';
PG.ostores=()=>{const o=D().online;return head(['Onlinebutiker'],'Onlinebutiker')+`<div class="bsbody"><h2>Yabie Online</h2><p class="lead" style="max-width:640px">Gästerna beställer i mobilen via QR-kod eller länk. Beställningen går direkt till kassan och köket. Kontakta sales@yabie.com för att aktivera tjänsten.</p>
 <div class="card" style="margin-top:14px" data-g="ostore-row"><span class="c1">Kaffebaren Online</span><span class="c2">${o.store?'Aktiv':'Inte inställd'}</span><span class="c3">order.yabie.com/${esc(F('b_osurl')||o.url||'kaffebaren')}</span><span class="act">${ibtn('edit','bsgo','ostore','ostore-edit','Redigera')} ${ibtn('table_restaurant','bsostable','','ostore-tables','Bordshantering')}</span></div></div>`};
A.bsostable=()=>{go('ostore');B().tab='tables';render();emit('bs:tab:tables')};
INIT.ostore=()=>{const o=D().online;Object.assign(UI.f,{b_osmail:o.mail||'',b_osurl:o.url||'kaffebaren',b_osmeth:o.meth||'both'})};
PG.ostore=()=>{const t=B().tab||'set';const o=D().online;return head(['Onlinebutiker','Kaffebaren Online'],'Kaffebaren Online')+`<div class="bsbody">${tabs('os',[['set','Butiksinställningar'],['tables','Bordshantering']],'set')}
 ${t==='set'?`<h3 style="margin-top:0">QR-koder</h3><div class="crow">${actPill('Ladda ner QR-kod','bsqrdl2','os-qr','','qr_code')}<span class="note" style="margin:0">Finns även som A4- och A5-mall</span></div><hr>
  <div class="grid2"><div>${lbl('Butik och licens',1)}${dd('b_oslic',['Kaffebaren – Kassa 1'],'Kaffebaren – Kassa 1')}</div><div>${lbl('Välj webbadress')}<div class="crow" style="margin:0"><span style="font-size:11.5px;color:#666">order.yabie.com/</span>${inp('b_osurl')}</div></div><div>${lbl('E-postadress för kundkontakt',1)}${inp('b_osmail',{ph:'info@kaffebaren.se'})}</div></div>
  <h3>Beställningsmetod</h3>${rad('b_osmeth','take','Ta med','both')}${rad('b_osmeth','eat','Äta här','both')}${rad('b_osmeth','both','Ta med och Äta här','both')}<hr>
  <h3 style="margin-top:0">Öppettider</h3><div class="days">${['Mån','Tis','Ons','Tor','Fre','Lör','Sön'].map((d,i)=>`<button class="${i<6?'on':''}">${d} ${i<5?'07–18':i<6?'09–16':'Stängt'}</button>`).join('')}</div><hr>
  <h3 style="margin-top:0">Information för kunder</h3>${rad('b_osinfo','info','Info (blå)','info')}${rad('b_osinfo','warn','Varning (röd)','info')}<div style="width:580px;margin-top:8px">${ta('b_osmsg')}</div><hr>
  <h3 style="margin-top:0">Produkter</h3><p class="lead">Välj vilka grupper eller produkter som visas online. Produkter med öppet pris, varianter och andra enheter än styck stöds inte.</p>${BS.pickedTable('online',580)}<div style="max-width:580px">${addBox('Välj produkter','bspick','online','os-prods')}</div><hr>
  <h3 style="margin-top:0">Beställningsinställningar</h3><div class="tgrow">Beställningsacceptans${tgl('b_osacc')}</div><div class="note">Gör automatisk acceptans möjlig att slå på i kassan.</div>
  <h3>Allergeninställningar</h3>${chk('b_osall','Visa allergener och specialkost',1)}${chk('b_osreq','Tillåt allergiönskemål')}`:
 `<p class="lead">Gästerna kopplar beställningen till sin plats. Du behöver minst en sektion med minst ett bord.</p><div class="rowr">${actPill('Skapa en ny bordssektion','bsossec','os-sec-add')}</div>${o.sections.map((s,i)=>`<div class="card" data-g="os-sec-${slug(s.name)}"><span class="c1">${esc(s.name)}</span><span class="c3">${s.tables.map(esc).join(', ')}</span><span class="act">${ibtn('qr_code','bsqrdl2','','os-tqr-'+i,'QR-koder (A6)')}</span></div>`).join('')||'<p class="lead"><i>Inga bordssektioner ännu.</i></p>'}
  ${B().dlg==='ossec'?dlg('Skapa en ny bordssektion',`${lbl('Namn',1)}${inp('b_ossname',{ph:'t.ex. Matsalen eller Utomhus'})}<div style="margin-top:10px">${lbl('Bord (kommaseparerade)',1)}${inp('b_osstables',{ph:'Bord 1, Bord 2, Bord 3'})}</div>`,`<button data-a="bsdlgx">Avbryt</button><button class="p" data-a="bsossecok" data-g="os-sec-save">Spara</button>`,{h:300}):''}`}</div>`+pickDlg()};
FOOT.ostore=()=>(B().tab||'set')==='set'?foot('bssaveos'):'';
