A.bsossecok=()=>{if(!need(['b_ossname','b_osstables']))return;D().online.sections.push({name:F('b_ossname').trim(),tables:F('b_osstables').split(',').map(s=>s.trim()).filter(Boolean)});save();B().dlg=null;render();btoast('Bordssektionen har skapats');emit('bs:save:ossec')};
A.bssaveos=()=>{if(!need(['b_osmail']))return;const o=D().online;Object.assign(o,{store:1,mail:F('b_osmail'),url:F('b_osurl'),meth:F('b_osmeth')||'both'});save();btoast('Onlinebutiken har sparats');emit('bs:save:os')};

