sub('userform','Lägg till ny användare','userlist');sub('user','Användare','userlist');BACK.userform='userlist';BACK.user='userlist';
const ROLES=['Personal','Butikschef','Backstage-användare'];
PG.userlist=()=>{const U=D().users;return head(['Användare'],'Användare')+`<div class="bsbody"><h2>Hantera dina användarkonton</h2><p class="lead">Här kan du skapa och hantera användarkonton, behörigheter och åtkomst för din personal och dina administratörer</p><hr>
 <div class="rowr">${addPill('Lägg till ny användare','userform','bs-user-add')}</div>${tool('Sök på användarnamn eller e-post','4/4')}
 <table class="bt"><tr><th>Namn ▲</th><th>Användarnamn</th><th>Roll</th><th>Personnummer</th><th>PIN-kod</th><th style="width:50px"></th></tr>${U.map((u,i)=>[u,i]).sort((a,b)=>a[0].first.localeCompare(b[0].first,'sv')).map(([u,i])=>`<tr data-g="user-${slug(u.first+' '+u.last)}"><td>${esc(u.first+' '+u.last)}</td><td>${esc(u.user)}</td><td>${esc(u.role)}</td><td>${u.id?'<span class="ms" style="font-size:16px">visibility</span>':'-'}</td><td>${u.pin?'<span class="ms" style="font-size:16px">visibility</span>':'-'}</td><td>${ibtn('open_in_new','bsgo','user|'+i,'user-open-'+slug(u.first+' '+u.last))}</td></tr>`).join('')}</table></div>`};
PG.userform=()=>head(['Användare','Lägg till ny användare'],'Lägg till ny användare')+`<div class="bsbody" style="padding-top:18px"><div style="width:284px">${lbl('Välj roll för användaren',1)}${dd('b_urole',ROLES,'Personal')}</div><hr>
 <div class="grid2"><div>${lbl('Förnamn',1)}${inp('b_ufirst')}</div><div>${lbl('Efternamn',1)}${inp('b_ulast')}</div><div>${lbl('PIN-kod',1)}${inp('b_upin',{type:'tel'})}<div class="help">PIN-koden används vid behov för att komma åt funktioner och kassörshantering i kassan samt för personalliggaren.</div></div><div>${lbl('Personnummer',1)}${inp('b_uid',{ph:'ÅÅÅÅMMDD-XXXX'})}<div class="help">Personnummer är obligatoriskt när personalliggaren används</div></div></div><hr>
 ${lbl('Vill du lägga till e-post, användarnamn och lösenord manuellt?')}${rad('b_uman','yes','Ja','no')}${rad('b_uman','no','Nej','no')}<hr><div class="info"><span class="ms">info</span>Du kan ändra användarens behörigheter efter att du har skapat användaren</div></div>`;
SAVES.userform=['bssaveuser'];
A.bssaveuser=()=>{if(!UI.f.b_urole)UI.f.b_urole='Personal';if(!need(['b_ufirst','b_ulast','b_upin','b_uid']))return;const pin=F('b_upin');if(!/^\d{4,10}$/.test(pin)||(D().set.pinlen!=='flex'&&pin.length!==4)){B().err.b_upin=1;render();btoast(D().set.pinlen==='flex'?'PIN-koden ska vara 4–10 siffror':'PIN-koden ska vara 4 siffror');return}
 const u={first:F('b_ufirst').trim(),last:F('b_ulast').trim(),user:(F('b_ufirst')+'.'+F('b_ulast')).toLowerCase().replace(/\s+/g,''),role:F('b_urole'),id:F('b_uid'),pin:'••••',perms:{}};D().users.push(u);
 S.cashiers=S.cashiers||[];S.cashiers.push({name:u.first+' '+u.last,role:u.role==='Personal'?'Kassör':'Admin',pin});save();go('userlist');btoast('Användaren har skapats');emit('bs:save:user',u)};
const PERMS=[['ret','Göra returer'],['disc','Ge rabatter'],['z','Göra dagsavslut (Z-rapport)'],['stats','Se försäljningsstatistik'],['drawer','Hantera växelkassan'],['cat','Ändra produktkatalogen i kassan']];
