PG.user=()=>{const u=D().users[+B().arg];return head(['Användare',u.first+' '+u.last],esc(u.first+' '+u.last))+`<div class="bsbody"><div class="grid2"><div>${lbl('Roll')}<input class="bi" value="${esc(u.role)}" readonly></div><div>${lbl('Användarnamn')}<input class="bi" value="${esc(u.user)}" readonly></div></div><div class="note">Användarnamnet används för att logga in i kassan.</div><hr>
 <h3 style="margin-top:0">Behörigheter</h3><p class="lead">Anpassade behörigheter för användaren. Standardbehörigheterna för en roll ändrar du under Användare → Inställningar.</p><div class="plist" style="max-width:520px;margin-top:10px">${PERMS.map(([k,t])=>`<div style="justify-content:space-between">${t}${tgl('b_pm_'+k)}</div>`).join('')}</div></div>`};
SAVES.user=['bssaveuserperm'];
